package de.corporate.lc.user.service;
import de.corporate.lc.user.repository.AppUserRepository;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.*;import org.springframework.stereotype.Service;import java.util.stream.*;
@Service public class AppUserDetailsService implements UserDetailsService {private final AppUserRepository repo;private final de.corporate.lc.tenant.service.TenantMembershipService memberships;public AppUserDetailsService(AppUserRepository r,de.corporate.lc.tenant.service.TenantMembershipService memberships){repo=r;this.memberships=memberships;}@Override public UserDetails loadUserByUsername(String username){var u=repo.findByUsernameIgnoreCase(username).orElseThrow(()->new UsernameNotFoundException("Benutzer nicht gefunden"));u.validateRoleTenant();if(!de.corporate.lc.tenant.domain.Tenant.DEFAULT_ID.equals(u.getTenantId()))throw new org.springframework.security.authentication.DisabledException("Tenant access is not enabled.");de.corporate.lc.tenant.service.TenantMembershipService.Access access;try(var scope=de.corporate.lc.tenant.domain.TenantContext.open(de.corporate.lc.tenant.domain.Tenant.DEFAULT_ID)){access=memberships.requireActiveAccess(u.getId());}catch(org.springframework.security.access.AccessDeniedException denied){throw new org.springframework.security.authentication.DisabledException("Tenant access is not enabled.",denied);}var authorities=Stream.concat(Stream.of(new SimpleGrantedAuthority("ROLE_"+access.baseRole().name())),access.permissions().stream().map(permission->new SimpleGrantedAuthority("PERM_"+permission.name()))).toList();return User.withUsername(u.getUsername()).password(u.getPasswordHash()).authorities(authorities).disabled(!u.isActive()).build();}}
